import static org.mockito.Mockito.when;

public class AbstractScopeBuilder_shouldTraverse_TriageGen1Test extends CompilerTestCase {

    private TypedScopeCreator.AbstractScopeBuilder scopeBuilder;
    private NodeTraversal mockTraversal;
    private Scope mockScope;

    @Before
    public void setUp() {
        // We need a concrete implementation or a spy of the abstract class to test it
        // Since it's an abstract class, we use Mockito to create a partial mock or a subclass
        scopeBuilder = Mockito.spy(new TypedScopeCreator.AbstractScopeBuilder() {
            @Override
            public void visit(NodeTraversal t, Node n, Node parent) {
                // No-op implementation for testing shouldTraverse
            }
        });

        mockTraversal = mock(NodeTraversal.class);
        mockScope = mock(Scope.class);

        // Inject mock scope into the builder via reflection or internal setter if possible.
        // Given the context, we assume 'scope' is a field in the abstract class.
        // For the sake of this test, we assume the field is accessible or set via a mock setup.
        try {
            java.lang.reflect.Field scopeField = TypedScopeCreator.AbstractScopeBuilder.class.getDeclaredField("scope");
            scopeField.setAccessible(true);
            scopeField.set(scopeBuilder, mockScope);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testShouldTraverse_ParentIsNull() {
        when(mockTraversal.getInputId()).thenReturn("testId");
        Node n = createNode(Token.NAME, "foo");

        // descend = parent == null || ... -> true
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, null));
    }

    @Test
    public void testShouldTraverse_ParentIsNotFunction() {
        when(mockTraversal.getInputId()).thenReturn("testId");
        Node n = createNode(Token.NAME, "foo");
        Node parent = createNode(Token.EXPR, "parent");

        // descend = parent == null || !parent.isFunction() -> true
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_IsFirstChildOfFunction() {
        when(mockTraversal.getInputId()).thenReturn("testId");
        Node n = createNode(Token.NAME, "child");
        Node parent = createNode(Token.FUNCTION, "func");
        parent.addChild(n);

        // descend = parent == null || !parent.isFunction() || n == parent.getFirstChild() -> true
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_ParentIsRootNode() {
        when(mockTraversal.getInputId()).thenReturn("testId");
        Node n = createNode(Token.NAME, "child");
        Node parent = createNode(Token.FUNCTION, "func");
        Node root = createNode(Token.BLOCK, "root");
        parent.addChild(n);

        when(mockScope.getRootNode()).thenReturn(root);

        // descend = ... || parent == scope.getRootNode() -> true
        // Note: The logic says parent == scope.getRootNode(). 
        // If parent is the root, it returns true.
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, root));
    }

    @Test
    public void testShouldTraverse_ReturnsFalseWhenInsideFunctionBody() {
        when(mockTraversal.getInputId()).thenReturn("testId");
        Node n = createNode(Token.NAME, "notFirstChild");
        Node parent = createNode(Token.FUNCTION, "func");
        Node firstChild = createNode(Token.NAME, "first");
        parent.addChild(firstChild);
        parent.addChild(n);

        Node root = createNode(Token.BLOCK, "root");
        when(mockScope.getRootNode()).thenReturn(root);

        // parent is function, n is not first child, parent is not root
        // descend = false || false || false || false -> false
        assertFalse(scopeBuilder.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_FunctionOrScriptTriggersPreconditions() {
        when(mockTraversal.getInputId()).thenReturn("testId");
        Node n = createNode(Token.FUNCTION, "func");

        // This tests the n.isFunction() branch and Preconditions.checkNotNull(inputId)
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, null));
    }

    @Test(expected = NullPointerException.class)
    public void testShouldTraverse_NullInputIdTriggersException() {
        when(mockTraversal.getInputId()).thenReturn(null);
        Node n = createNode(Token.FUNCTION, "func");

        // Should throw NPE because n.isFunction() is true and inputId is null
        scopeBuilder.shouldTraverse(mockTraversal, n, null);
    }

    @Test
    public void testShouldTraverse_HoistedFunctionDetection() {
        when(mockTraversal.getInputId()).thenReturn("testId");

        // n is a statement parent
        Node n = createNode(Token.BLOCK, "block");
        Node hoisted = createNode(Token.FUNCTION, "hoisted");
        // We need NodeUtil.isHoistedFunctionDeclaration(child) to be true.
        // Since NodeUtil is static, this depends on the state of the Node.
        // In Closure Compiler, a function declaration is often identified by its type.
        n.addChild(hoisted);

        // We mock/setup the node to satisfy NodeUtil.isStatementParent(n) and NodeUtil.isHoistedFunctionDeclaration(child)
        // In a real test environment, you'd use actual AST nodes that satisfy these conditions.
        // For this unit test, we assume the environment allows these calls to pass or we use specific node types.

        // If descend is true, it iterates children.
        assertTrue(scopeBuilder.shouldTraverse(mockTraversal, n, null));
    }
}
